scwin.isChkBzCalnd = false;

scwin.w = '375';

scwin.h = '220';

scwin.indCodeWin = null;

scwin.instCodeWin = null;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_basicComInfo.get("comNm")) + "(" + String(dma_basicComInfo.get("isurCd")) + ")"; } },
        { childId: "__rb1", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb2", attr: "label", fn: function () { return String(dma_basicComInfo.get("mktTpNm")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_basicComInfo.get("secugrpNm")); } },
        { childId: "txa_majshrhdContn", attr: "label", fn: function () { return String(dma_newListApplContn.get("majshrhdContn")); } },
        { childId: "txa_remk", attr: "label", fn: function () { return String(dma_newListApplContn.get("remk")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "ipt_isurCd", fn: function(){ return ((String(((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })())) == null ? '' : ((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })()))).length === 0)); } }, { id: "ipt_isurCd_2", fn: function(){ return (!(String(((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })())) == null ? '' : ((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })()))).length === 0)); } }, { id: "c_when_229_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })()) == 0); } }, { id: "c_otherwise_230", fn: function(){ return (!(((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })()) == 0))); } }, { id: "c_when_291_txt", fn: function(){ return ((String(((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })())) == null ? '' : ((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })()))).length === 0)); } }, { id: "c_otherwise_292", fn: function(){ return (!(((String(((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })())) == null ? '' : ((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })()))).length === 0)))); } }, { id: "btn_register", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modifyYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modifyYn"))=== 'Y' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pubofrWrtYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("pubofrWrtYn"))!== 'N'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_227", entity: "dlt_leadCom", countIds: [], cells: [{ childId: "__rc5", fn: function (v, i) { return String(v("name")); } }, { childId: "__rc6", fn: function (v, i) { return ", " + String(v("name")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_process", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("process")))); } },
        { childId: "ipt_isurCd", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurCd"))); } },
        { childId: "ipt_corpRegNo1", fn: function () { return String(String(String(dma_newListApplContn.get("corpRegNo"))).substring(0, 6)); } },
        { childId: "ipt_corpRegNo2", fn: function () { return String(String(String(dma_newListApplContn.get("corpRegNo"))).substring(6, 13)); } },
        { childId: "ipt_bzRegNo1", fn: function () { return String(String(String(dma_newListApplContn.get("bzRegNo"))).substring(0, 3)); } },
        { childId: "ipt_bzRegNo2", fn: function () { return String(String(String(dma_newListApplContn.get("bzRegNo"))).substring(3, 5)); } },
        { childId: "ipt_bzRegNo3", fn: function () { return String(String(String(dma_newListApplContn.get("bzRegNo"))).substring(5, 10)); } },
        { childId: "__rb4", fn: function () { return " " + String(dma_newListApplContn.get("leadcomMbrNm")) + " " + String(dma_newListApplContn.get("speclListTpNm")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const majshrhdContn = $c.util.getComponent("dma_registerReq").get("majshrhdContn");
        scwin.setLength(majshrhdContn, 'tdMajshrhdContn', '500');
        const remk = $c.util.getComponent("dma_registerReq").get("remk");
        scwin.setLength(remk, 'tdRemk', '2000');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55300n.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil55300n' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(newlistapplcontn vs >-) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.l = undefined; try { scwin.l = /* sdd-asis-lifecycle:begin l — as-is 원문 본문(전환 이관 · 포팅 적용됨) */screen.width/2 - scwin.w/2/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil55300n' }); }

scwin.t = undefined; try { scwin.t = /* sdd-asis-lifecycle:begin t — as-is 원문 본문(전환 이관 · 포팅 적용됨) */screen.height/2 - scwin.h/2/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil55300n' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil55300n.onpageload' });
    }
};


