        $c.util.getComponent('ipt_comEngNm').select();
        return;
    } else {
        if (scwin.calBytes($c.util.getComponent('ipt_comEngNm').getValue()) > 60) {
            await $c.win.alert('영문회사명 최대길이 60자를 초과하였습니다.');
            $c.util.getComponent('ipt_comEngNm').select();
            return;
        }
    }
    if (($c.util.getComponent('ipt_comAbbrv').getValue() == null ? '' : String($c.util.getComponent('ipt_comAbbrv').getValue())) === '') {
        await $c.win.alert('회사약명을 입력하십시오');
        $c.util.getComponent('ipt_comAbbrv').select();
        return;
    } else {
        if (scwin.calBytes($c.util.getComponent('ipt_comAbbrv').getValue()) > 30) {
            await $c.win.alert('회사약명 최대길이 15자를 초과하였습니다.');
            $c.util.getComponent('ipt_comAbbrv').select();
            return;
        }
    }
    if (($c.util.getComponent('ipt_comEngAbbrv').getValue() == null ? '' : String($c.util.getComponent('ipt_comEngAbbrv').getValue())) === '') {
        await $c.win.alert('영문회사약명을 입력하십시오');
        $c.util.getComponent('ipt_comEngAbbrv').select();
        return;
    } else {
        if (scwin.calBytes($c.util.getComponent('ipt_comEngAbbrv').getValue()) > 30) {
            await $c.win.alert('영문회사약명 최대길이 30자를 초과하였습니다.');
            $c.util.getComponent('ipt_comEngAbbrv').select();
            return;
        }
    }
    if (($c.util.getComponent('ipt_comAddr').getValue() == null ? '' : String($c.util.getComponent('ipt_comAddr').getValue())) === '') {
        await $c.win.alert('회사 주소를 입력하십시오');
        $c.util.getComponent('ipt_comAddr').select();
        return;
    }
    if (($c.util.getComponent('ipt_repNm').getValue() == null ? '' : String($c.util.getComponent('ipt_repNm').getValue())) === '') {
        await $c.win.alert('대표자명을 입력 하십시오');
        $c.util.getComponent('ipt_repNm').select();
        return;
    }
    if ($c.util.getComponent("dma_registerReq").get("corpRegNo") === '') {
        await $c.win.alert('회사등록번호를 입력하십시오');
        frm.corpRegNo.select();
        return;
    }
    if (($c.util.getComponent('ipt_stdIndCd').getValue() == null ? '' : String($c.util.getComponent('ipt_stdIndCd').getValue())) === '') {
        await $c.win.alert('업종을  입력 하십시오');
        $c.util.getComponent('ipt_stdIndCd').select();
        return;
    }
    if (($c.util.getComponent('cal_foundDd').getValue() == null ? '' : String($c.util.getComponent('cal_foundDd').getValue())) === '') {
        await $c.win.alert('설립일을  입력 하십시오');
        $c.util.getComponent('cal_foundDd').select();
        return;
    }
    if ($c.util.getComponent('slc_spotIsuTrdMktTpCd').getValue() === '') {
        await $c.win.alert('시장구분을 입력하십시오');
        $c.util.getComponent("slc_spotIsuTrdMktTpCd").focus();
        return;
    }
    if (!await scwin.checkCorpRegNo()) {
        return;
    }
    if (!await scwin.checkBzRegNo()) {
        return;
    }
    if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) === '') {
        await $c.win.alert('상장(희망)일을 입력하여 주십시오');
        return;
    } else {
        if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) !== '') {
            if ($c.util.getComponent("dma_registerReq").get("possibleYn") !== 'Y') {
                await $c.win.alert('상장(희망)일 중복체크를 하여 주십시오');
                return;
            }
        }
    }
    if (($c.util.getComponent('slc_ventbzYn').getValue() == null ? '' : String($c.util.getComponent('slc_ventbzYn').getValue())) === '') {
        await $c.win.alert('벤처기업여부를 입력하십시오');
        $c.util.getComponent("slc_ventbzYn").focus();
        return;
    }
    if ('' + dma_newListApplContn.get("speclListTpCd") + '' === '02') {
        if (($c.util.getComponent('ipt_crwfndAmt1').getValue() == null ? '' : String($c.util.getComponent('ipt_crwfndAmt1').getValue())) === '') {
            await $c.win.alert('크라우드펀딩특례상장으로 펀딩금액을 입력하여 주십시오');
            $c.util.getComponent("ipt_crwfndAmt1").focus();
            return;
        }
        if (($c.util.getComponent('ipt_crwfndInvstNm').getValue() == null ? '' : String($c.util.getComponent('ipt_crwfndInvstNm').getValue())) === '') {
            await $c.win.alert('크라우드펀딩특례상장으로 전문투자자를 입력하여 주십시오');
            $c.util.getComponent("ipt_crwfndInvstNm").focus();
            return;
        }
        if (($c.util.getComponent('ipt_crwfndProfsInvstNm').getValue() == null ? '' : String($c.util.getComponent('ipt_crwfndProfsInvstNm').getValue())) === '') {
            await $c.win.alert('크라우드펀딩특례상장으로 투자자를 입력하여 주십시오');
            $c.util.getComponent("ipt_crwfndProfsInvstNm").focus();
            return;
        }
        if (($c.util.getComponent('ipt_crwfndBrokerNm').getValue() == null ? '' : String($c.util.getComponent('ipt_crwfndBrokerNm').getValue())) === '') {
            await $c.win.alert('크라우드펀딩특례상장으로 중개업자를 입력하여 주십시오');
            $c.util.getComponent("ipt_crwfndBrokerNm").focus();
            return;
        }
    }
    if ($c.util.getComponent('ipt_hpage').getValue().toLowerCase().indexOf("://") > -1) {
        await $c.win.alert("'http://'를 제외한 홈페이지를 입력하세요.");
        $c.util.getComponent("ipt_hpage").focus();
        return;
    }
    const process = $c.util.getComponent("dma_registerReq").get("process");
    const listProcsSeq = $c.util.getComponent("dma_registerReq").get("listProcsSeq");
    if (process === '2' && listProcsSeq === '') {
        $c.util.getComponent("dma_registerReq").set("listProcsSeq", '1');
        if (($c.util.getComponent('ipt_isurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_isurCd').getValue())) === '') {
            $c.util.getComponent("ipt_isurCd").setValue($c.util.getComponent('ipt_isurCd').getValue());
        }
        if ($c.util.getComponent("dma_registerReq").get("pubofrSchdlDd") === '') {
            $c.util.getComponent("dma_registerReq").set("pubofrSchdlDd", 'X');
        }
    }
    if ($c.util.getComponent("dma_registerReq").get("listProcsSeq") === '1') {
        $c.util.getComponent("dma_registerReq").set("method", 'insertNewListApplContn');
    } else {
        if ($c.util.getComponent("dma_registerReq").get("listProcsSeq") === '2') {
            $c.util.getComponent("dma_registerReq").set("method", 'updateNewListApplContn');
        }
    }
    $c.util.getComponent("dma_registerReq").set("crwfndAmt", $c.util.getComponent('ipt_crwfndAmt1').getValue().split(",").join(""));
    if ('' + dma_newListApplContn.get("speclListTpNm") + '' !== '') {
        $c.util.getComponent("dma_registerReq").set("leadcomMbrNm", '' + dma_newListApplContn.get("speclListTpNm") + '');
    } else {
        if (($c.util.getComponent('ipt_leadcomMbrNm').getValue() == null ? '' : String($c.util.getComponent('ipt_leadcomMbrNm').getValue())) !== '') {
            $c.util.getComponent("dma_registerReq").set("leadcomMbrNm", $c.util.getComponent('ipt_leadcomMbrNm').getValue());
        } else {
            for (let i = 0; i < dlt_leadCom.getRowCount(); i++) {
                $c.util.getComponent("dma_registerReq").set("leadcomMbrNm", (String(((dlt_leadCom.getCellData(i, "name") ?? (() => { throw new Error("unresolved:" + "leadCom[__i].name"); })())) == null ? '' : ((dlt_leadCom.getCellData(i, "name") ?? (() => { throw new Error("unresolved:" + "leadCom[__i].name"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_leadCom.getCellData(i, "name") ?? (() => { throw new Error("unresolved:" + "leadCom[__i].name"); })())) == null ? '' : ((dlt_leadCom.getCellData(i, "name") ?? (() => { throw new Error("unresolved:" + "leadCom[__i].name"); })())))));
            }
        }
    }
    $c.util.getComponent('slc_listClssCd').setDisabled(false);
    $c.util.getComponent('slc_spotIsuTrdMktTpCd').setDisabled(false);
    frm.action = 'newListApplContn.do';
    { const nr = await scwin.tx_fn_register(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil55300/jldfil55300.xml", { "listProcsSeq": '1', "pubofrSchdlDd": 'X', "method": 'insertNewListApplContn', "leadcomMbrNm": '' + dma_newListApplContn.get("speclListTpNm") + '' }); } };
    /* sdd-asis-lifecycle:end */
};


