/**
 * @method
 * @name scwin.filterKey
 * @author Inswave
 * @date 2026. 09. 29
 * @param filter
 * @returns
 * @hidden N
*/
scwin.filterKey = function (filter) {
    /* sdd-asis-lifecycle:begin filterKey — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (filter) {
        const sKey = String.fromCharCode($c.util.getKeyCode(event));
        const re = new RegExp(filter);
        if (!re.test(sKey)) {
            event.returnValue = false;
        }
    }
    /* sdd-asis-lifecycle:end */
};


